export interface PageMeta {
  title: string;
  date?: string;
  tags?: string[];
}

export interface Page extends PageMeta {
  slug: string;
  content: string;
  html: string;
}

import { Page } from './types';

export function pageTemplate(page: Page): string {
  const tagList = page.tags && page.tags.length > 0
    ? page.tags.map((t) => `<span class="tag">${escapeHtml(t)}</span>`).join(' ')
    : '';

  return `<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>${escapeHtml(page.title)}</title>
  <style>
    body { font-family: system-ui, sans-serif; max-width: 720px; margin: 0 auto; padding: 2rem; line-height: 1.6; color: #222; }
    .tag { display: inline-block; background: #e2e8f0; padding: 0.1rem 0.5rem; border-radius: 4px; font-size: 0.85rem; margin-right: 0.25rem; }
    .date { color: #666; font-size: 0.9rem; }
    nav { margin-bottom: 2rem; }
    nav a { color: #1a56db; }
    h1 { margin-bottom: 0.25rem; }
  </style>
</head>
<body>
  <nav><a href="index.html">&larr; Home</a></nav>
  <h1>${escapeHtml(page.title)}</h1>
  ${page.date ? `<p class="date">${escapeHtml(page.date)}</p>` : ''}
  ${tagList ? `<p>${tagList}</p>` : ''}
  <hr>
  ${page.html}
</body>
</html>`;
}

export function indexTemplate(pages: Page[]): string {
  const items = pages
    .map(
      (p) => `<li><a href="${escapeHtml(p.slug)}.html">${escapeHtml(p.title)}</a>${p.date ? ` <span class="date">— ${escapeHtml(p.date)}</span>` : ''}</li>`
    )
    .join('\n      ');

  return `<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>Index</title>
  <style>
    body { font-family: system-ui, sans-serif; max-width: 720px; margin: 0 auto; padding: 2rem; line-height: 1.6; color: #222; }
    .date { color: #666; font-size: 0.9rem; }
    h1 { margin-bottom: 0.5rem; }
    ul { padding-left: 1.2rem; }
    li { margin-bottom: 0.25rem; }
  </style>
</head>
<body>
  <h1>All Pages</h1>
  <ul>
      ${items}
  </ul>
  ${pages.length === 0 ? '<p>No pages found.</p>' : ''}
</body>
</html>`;
}

function escapeHtml(text: string): string {
  return text
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;');
}

import * as fs from 'fs';
import * as path from 'path';
import matter from 'gray-matter';
import { marked } from 'marked';
import { Page } from './types';
import { pageTemplate, indexTemplate } from './template';

export function build(contentDir: string, outputDir: string): void {
  const absoluteContent = path.resolve(contentDir);

  if (!fs.existsSync(absoluteContent)) {
    throw new Error(`Content directory does not exist: ${absoluteContent}`);
  }

  const files = fs.readdirSync(absoluteContent).filter((f) => f.endsWith('.md'));

  const pages: Page[] = [];

  for (const file of files) {
    const filePath = path.join(absoluteContent, file);
    const slug = path.basename(file, '.md');
    const raw = matter.read(filePath);
    const html = marked.parse(raw.content) as string;

    const page: Page = {
      slug,
      title: raw.data.title || slug,
      date: raw.data.date || undefined,
      tags: raw.data.tags || undefined,
      content: raw.content,
      html,
    };

    pages.push(page);
  }

  pages.sort((a, b) => {
    if (a.date && b.date) {
      return b.date.localeCompare(a.date);
    }
    if (a.date) return -1;
    if (b.date) return 1;
    return a.title.localeCompare(b.title);
  });

  const absoluteOutput = path.resolve(outputDir);
  if (!fs.existsSync(absoluteOutput)) {
    fs.mkdirSync(absoluteOutput, { recursive: true });
  }

  for (const page of pages) {
    const html = pageTemplate(page);
    fs.writeFileSync(path.join(absoluteOutput, `${page.slug}.html`), html);
  }

  const indexHtml = indexTemplate(pages);
  fs.writeFileSync(path.join(absoluteOutput, 'index.html'), indexHtml);
}

#!/usr/bin/env node
import { Command } from 'commander';
import { build } from './build';

const program = new Command();

program
  .name('ssg')
  .description('Static site generator — converts Markdown files to HTML');

program
  .command('build')
  .description('Generate the site from Markdown files')
  .option('--content <dir>', 'Content directory containing Markdown files', './content')
  .option('--output <dir>', 'Output directory for generated HTML files', './dist')
  .action((options) => {
    try {
      build(options.content, options.output);
      console.log(`Site built successfully. Output: ${options.output}`);
    } catch (err) {
      const message = err instanceof Error ? err.message : String(err);
      console.error(`Error: ${message}`);
      process.exit(1);
    }
  });

program.parse(process.argv);

